from typing import List
from collections import defaultdict

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        children = []
        count = []
        depth = []

        children.append({})
        count.append(0)
        depth.append(0)

        paths = []
        max_depth = 0

        for word in words:
            node = 0
            count[node] += 1
            path = []
            for ch in word:
                if ch not in children[node]:
                    children[node][ch] = len(children)
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)
                node = children[node][ch]
                count[node] += 1
                path.append(node)
            paths.append(path)
            max_depth = max(max_depth, len(word))

        good_by_depth = [0] * (max_depth + 1)
        for node in range(1, len(count)):
            if count[node] >= k:
                good_by_depth[depth[node]] += 1

        size = 1
        while size <= max_depth:
            size *= 2

        seg = [0] * (2 * size)
        for d in range(1, max_depth + 1):
            if good_by_depth[d] > 0:
                seg[size + d] = d

        for idx in range(size - 1, 0, -1):
            seg[idx] = max(seg[idx * 2], seg[idx * 2 + 1])

        def set_depth(d: int, active: bool) -> None:
            pos = size + d
            seg[pos] = d if active else 0
            pos //= 2
            while pos:
                seg[pos] = max(seg[pos * 2], seg[pos * 2 + 1])
                pos //= 2

        ans = []

        for path in paths:
            changed = []

            for node in path:
                if count[node] == k:
                    d = depth[node]
                    good_by_depth[d] -= 1
                    if good_by_depth[d] == 0:
                        set_depth(d, False)
                    changed.append(d)

            ans.append(seg[1])

            for d in changed:
                was_zero = good_by_depth[d] == 0
                good_by_depth[d] += 1
                if was_zero:
                    set_depth(d, True)

        return ans
